-- ═══════════════════════════════════════════════════════════════════════════
-- Awami Market · Fifth Floor, revised plan (AWAMI MARKIT.pdf, 25 Sep 2026)
-- Generated by make_sql.js on 2026-09-29; nothing in the VALUES list was typed.
--
-- 136 old units (5F-01 .. 5F-136, one-room "UNIT"s) become 97 flats (5F-501 .. 5F-597):
--   * 97 old rows are KEPT and renamed (their id survives, so 5F-01's two
--     cancelled reservations and its request stay attached to 5F-501);
--   * 39 old rows that were merged into a neighbour are DELETED — none has a
--     sale, token, active booking, lead, quote, transfer or any other reference.
-- area   : the PDF's AREA= label; 523/524/566 keep their old area (878.00 / 575.20 /
--          578.79) on the owner's word — the PDF's 478.25 / 475.20 / 678.80 disagree
--          with the rooms drawn on the same sheet.
-- price  : area x 11,000 (the floor's current rate, unchanged).
-- type   : read off the drawing (Studio 9, 1 Bed 49, 2 Bed 34, 3 Bed 5).
-- Totals after: 97 units, 73395.27 sq ft, PKR 807347970.00.
-- The block refuses to run unless the floor is exactly as it was checked: 136 units,
-- all Available, nothing sold, nothing actively held.
-- ═══════════════════════════════════════════════════════════════════════════

DO $mig$
DECLARE
  v_pr constant uuid := '59ded55b-9bc2-45b2-a372-49fc31807fa9';
  v_n int; v_bad int; v_area numeric; v_price numeric; v_missing int;
BEGIN
  /* ── the floor must be exactly what was checked ── */
  SELECT count(*) INTO v_n FROM public.units WHERE project_id = v_pr AND floor_label = 'Fifth Floor';
  IF v_n <> 136 THEN RAISE EXCEPTION 'expected 136 Fifth Floor units, found %', v_n; END IF;
  SELECT count(*) INTO v_bad FROM public.units u
    LEFT JOIN public.category_unit_statuses cs ON cs.id = u.status_id
   WHERE u.project_id = v_pr AND u.floor_label = 'Fifth Floor' AND NOT COALESCE(cs.is_available, false);
  IF v_bad > 0 THEN RAISE EXCEPTION '% Fifth Floor units are no longer Available — stop and re-check', v_bad; END IF;
  SELECT count(*) INTO v_bad FROM public.reservations r JOIN public.units u ON u.id = r.unit_id
   WHERE u.project_id = v_pr AND u.floor_label = 'Fifth Floor' AND r.status = 'active';
  IF v_bad > 0 THEN RAISE EXCEPTION '% active reservations on the Fifth Floor — stop', v_bad; END IF;
  SELECT count(*) INTO v_bad FROM public.sales s JOIN public.units u ON u.id = s.unit_id
   WHERE u.project_id = v_pr AND u.floor_label = 'Fifth Floor';
  IF v_bad > 0 THEN RAISE EXCEPTION '% sales on the Fifth Floor — stop', v_bad; END IF;

  CREATE TEMP TABLE _f5 (keep text, new_no text, area numeric, price numeric, type_name text) ON COMMIT DROP;

  SELECT count(*) INTO v_missing FROM _f5 f
   WHERE NOT EXISTS (SELECT 1 FROM public.units u WHERE u.project_id = v_pr AND u.unit_no = f.keep)
      OR NOT EXISTS (SELECT 1 FROM public.category_unit_types t WHERE t.project_id = v_pr AND t.type_name = f.type_name);
  IF v_missing > 0 THEN RAISE EXCEPTION '% rows refer to a unit or type that is not there', v_missing; END IF;

  /* ── the 39 merged-away rows go first, so no rename can collide ── */
  DELETE FROM public.units u
   WHERE u.project_id = v_pr AND u.floor_label = 'Fifth Floor'
     AND u.unit_no NOT IN (SELECT keep FROM _f5);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n <> 39 THEN RAISE EXCEPTION 'deleted % rows, expected 39', v_n; END IF;

  /* ── the 97 kept rows become the new flats ── */
  UPDATE public.units u
     SET unit_no = f.new_no, unit_code = f.new_no, area = f.area, base_price = f.price,
         unit_type_id = (SELECT t.id FROM public.category_unit_types t
                          WHERE t.project_id = v_pr AND t.type_name = f.type_name)
    FROM _f5 f
   WHERE u.project_id = v_pr AND u.unit_no = f.keep;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n <> 97 THEN RAISE EXCEPTION 'updated % rows, expected 97', v_n; END IF;

  /* ── and the floor adds up ── */
  SELECT count(*), sum(area), sum(base_price) INTO v_n, v_area, v_price
    FROM public.units WHERE project_id = v_pr AND floor_label = 'Fifth Floor';
  IF v_n <> 97 OR v_area <> 73395.27 OR v_price <> 807347970.00 THEN
    RAISE EXCEPTION 'after: % units, % sq ft, % PKR — not the expected 97 / 73395.27 / 807347970.00', v_n, v_area, v_price;
  END IF;
END $mig$;
